#!/usr/bin/env bash
set -euo pipefail

API_KEY="${BUILDBUDDY_API_KEY:-}"
ENDPOINT="${BUILDBUDDY_ENDPOINT:-manuelfrancisconaranjo.buildbuddy.io}"
# Strip protocol prefixes if present
ENDPOINT="${ENDPOINT#grpcs://}"
ENDPOINT="${ENDPOINT#https://}"

if [ -z "${API_KEY}" ]; then
  echo "BUILDBUDDY_API_KEY is not set. Routing CI through local Docker sandbox."
  cat > .bazelrc.user << EOF
# Auto-generated by CI: fallback to docker sandbox when API key is missing
build:ci --config=docker
EOF
  exit 0
fi

echo "Configuring Bazel remote cluster for endpoint: ${ENDPOINT}"

cat > .bazelrc.user << EOF
# Auto-generated by CI to connect to BuildBuddy remote cluster
build:rc --bes_results_url=https://${ENDPOINT}/invocation/
build:rc --bes_backend=grpcs://${ENDPOINT}
build:rc --remote_cache=grpcs://${ENDPOINT}
build:rc --remote_timeout=10m
build:rc --remote_header=x-buildbuddy-api-key=${API_KEY}
build:rc --remote_cache_compression
build:rc --experimental_remote_cache_chunking
build:rc --experimental_repo_remote_exec
build:rc --noslim_profile --experimental_profile_include_target_label --experimental_profile_include_primary_output

build:rbe --config=rc
build:rbe --remote_executor=grpcs://${ENDPOINT}
build:rbe --remote_download_outputs=minimal
build:rbe --remote_timeout=10m
build:rbe --platforms=@toolchains_buildbuddy//platforms:linux_x86_64
build:rbe --extra_execution_platforms=@toolchains_buildbuddy//platforms:linux_x86_64
build:rbe --jobs 40

# When remote cluster is available, route ci builds through rbe
build:ci --config=rbe
EOF

echo "Generated .bazelrc.user successfully."
